const OPENROUTER_CHAT_COMPLETIONS_URL = process.env.OPENROUTER_CHAT_COMPLETIONS_URL || "https://openrouter.ai/api/v1/chat/completions";
const OPENROUTER_APP_TITLE = process.env.OPENROUTER_APP_TITLE || "Historicals Solver";
const OPENROUTER_SITE_URL = process.env.OPENROUTER_SITE_URL || "http://localhost:3000";
// The LLM is the responsible analyst, so use an accounting-capable frontier
// model for both primary statement work and recovery. A capable paid fallback
// prevents provider latency from silently downgrading the workbook to rules.
const DEFAULT_LLM_MAPPING_FAST_MODEL = "qwen/qwen3.7-plus";
const DEFAULT_LLM_MAPPING_COMPLEX_MODEL = "qwen/qwen3.7-plus";
const DEFAULT_LLM_MAPPING_REVIEW_MODEL = "qwen/qwen3.7-plus";
const DEFAULT_LLM_MAPPING_FAST_FALLBACK_MODELS = ["deepseek/deepseek-v4-flash"];
const DEFAULT_LLM_MAPPING_COMPLEX_FALLBACK_MODELS = ["deepseek/deepseek-v4-flash"];
const DEFAULT_LLM_MAPPING_REVIEW_FALLBACK_MODELS: string[] = [];
const LLM_MAPPING_FAST_MODEL = normalizeConfiguredLlmModel(
  process.env.LLM_MAPPING_FAST_MODEL || process.env.LLM_MAPPING_MODEL || DEFAULT_LLM_MAPPING_FAST_MODEL,
  DEFAULT_LLM_MAPPING_FAST_MODEL
);
const LLM_MAPPING_COMPLEX_MODEL = normalizeConfiguredLlmModel(
  process.env.LLM_MAPPING_COMPLEX_MODEL || process.env.LLM_MAPPING_STRONG_MODEL || DEFAULT_LLM_MAPPING_COMPLEX_MODEL,
  DEFAULT_LLM_MAPPING_COMPLEX_MODEL
);
const LLM_MAPPING_REVIEW_MODEL = normalizeConfiguredLlmModel(
  process.env.LLM_MAPPING_REVIEW_MODEL || DEFAULT_LLM_MAPPING_REVIEW_MODEL,
  DEFAULT_LLM_MAPPING_REVIEW_MODEL
);
const LLM_MAPPING_FAST_FALLBACK_MODELS = llmFallbackModels(
  process.env.LLM_MAPPING_FAST_FALLBACK_MODELS || process.env.LLM_MAPPING_FALLBACK_MODELS,
  DEFAULT_LLM_MAPPING_FAST_FALLBACK_MODELS,
  LLM_MAPPING_FAST_MODEL
);
const LLM_MAPPING_COMPLEX_FALLBACK_MODELS = llmFallbackModels(
  process.env.LLM_MAPPING_COMPLEX_FALLBACK_MODELS || process.env.LLM_MAPPING_FALLBACK_MODELS,
  DEFAULT_LLM_MAPPING_COMPLEX_FALLBACK_MODELS,
  LLM_MAPPING_COMPLEX_MODEL
);
const LLM_MAPPING_REVIEW_FALLBACK_MODELS = llmFallbackModels(
  process.env.LLM_MAPPING_REVIEW_FALLBACK_MODELS || process.env.LLM_MAPPING_FALLBACK_MODELS,
  DEFAULT_LLM_MAPPING_REVIEW_FALLBACK_MODELS,
  LLM_MAPPING_REVIEW_MODEL
);
// Deterministic accounting logic owns extraction, writes, and validation. The
// LLM is an opt-in fallback only for classifications that remain ambiguous.
const LLM_ANALYST_MODE =
  booleanEnv(process.env.ALLOW_LEGACY_LLM_WORKBOOK_REVIEW, false) &&
  booleanEnv(process.env.LLM_ANALYST_MODE, false);
const LLM_MAPPING_HARD_MAX_CALLS = positiveNumber(process.env.LLM_MAPPING_HARD_MAX_CALLS, 64);
const LLM_MAPPING_MAX_CALLS = boundedPositiveNumber(process.env.LLM_MAPPING_MAX_CALLS, 48, LLM_MAPPING_HARD_MAX_CALLS);
const LLM_MAPPING_REVIEW_RESERVED_CALLS = nonNegativeNumber(process.env.LLM_MAPPING_REVIEW_RESERVED_CALLS, 6);
const LLM_MAPPING_REVIEW_RESERVED_MS = nonNegativeNumber(process.env.LLM_MAPPING_REVIEW_RESERVED_MS, 300_000);
const LLM_MAPPING_REVIEW_MAX_ITEMS = boundedPositiveNumber(process.env.LLM_MAPPING_REVIEW_MAX_ITEMS, 180, 500);
const LLM_MAPPING_RECOVERY_MAX_ITEMS = boundedPositiveNumber(process.env.LLM_MAPPING_RECOVERY_MAX_ITEMS, 140, 500);
// A recovery review reasons across several interdependent statement equations.
// Frontier reasoning models can legitimately need more than two minutes for
// this pass, especially when the provider queues a large structured response.
const LLM_MAPPING_REVIEW_TIMEOUT_MS = Number(process.env.LLM_MAPPING_REVIEW_TIMEOUT_MS || 240_000);
const LLM_MAPPING_REVIEW_AUTOCORRECT =
  booleanEnv(process.env.ALLOW_LEGACY_LLM_WORKBOOK_REVIEW, false) &&
  booleanEnv(process.env.LLM_MAPPING_REVIEW_AUTOCORRECT, false);
const LLM_MAX_COST_PER_WORKBOOK_USD = nonNegativeNumber(process.env.LLM_MAX_COST_PER_WORKBOOK_USD, 0.1);
const LLM_UNUSED_ROW_MAPPING_ENABLED = booleanEnv(process.env.LLM_UNUSED_ROW_MAPPING_ENABLED, false);
const LLM_MAPPING_MIN_CANDIDATE_SCORE = Number(process.env.LLM_MAPPING_MIN_CANDIDATE_SCORE || 2);
const LLM_MAPPING_CANDIDATE_LIMIT = Number(process.env.LLM_MAPPING_CANDIDATE_LIMIT || 80);
const LLM_MAPPING_COMPLEX_SCORE = Number(process.env.LLM_MAPPING_COMPLEX_SCORE || 4);
const LLM_MAPPING_TIMEOUT_MS = Number(process.env.LLM_MAPPING_TIMEOUT_MS || 10_000);
// Keep LLM work inside the API's 15-minute request ceiling while leaving a
// protected recovery window after slow provider responses.
const LLM_TOTAL_TIMEOUT_MS = Math.min(Number(process.env.LLM_TOTAL_TIMEOUT_MS || 780_000), 780_000);
const LLM_WORKBENCH_MAX_FACTS = Number(process.env.LLM_WORKBENCH_MAX_FACTS || 500);
const LLM_WORKBENCH_MAX_STATEMENT_ROWS = Number(process.env.LLM_WORKBENCH_MAX_STATEMENT_ROWS || 650);
const LLM_WORKBENCH_MAX_WORKBOOK_CELLS = Number(process.env.LLM_WORKBENCH_MAX_WORKBOOK_CELLS || 700);
const LLM_WORKBENCH_MAX_AUDIT_ROWS = Number(process.env.LLM_WORKBENCH_MAX_AUDIT_ROWS || 500);
const LLM_WORKBENCH_MAX_SOURCE_LEDGER_ROWS = Number(process.env.LLM_WORKBENCH_MAX_SOURCE_LEDGER_ROWS || 600);
const LLM_WORKBENCH_MAX_BALANCE_ASSIGNMENTS = Number(process.env.LLM_WORKBENCH_MAX_BALANCE_ASSIGNMENTS || 500);
const LLM_WORKBENCH_MAX_INCOME_ASSIGNMENTS = Number(process.env.LLM_WORKBENCH_MAX_INCOME_ASSIGNMENTS || 500);
const LLM_WORKBENCH_MAX_SEGMENT_ASSIGNMENTS = Number(process.env.LLM_WORKBENCH_MAX_SEGMENT_ASSIGNMENTS || 500);
// Stored XLSX entries are larger but avoid minutes of duplicate DEFLATE work during interactive downloads.
const FAST_XLSX_ZIP_OPTIONS = {
  compression: "STORE" as const
};
const LLM_LINE_ITEM_CLASSIFICATION_MAX_CALLS = Number(
  Math.min(
    boundedPositiveNumber(
      process.env.LLM_LINE_ITEM_CLASSIFICATION_MAX_CALLS,
      Math.min(LLM_MAPPING_MAX_CALLS, 12),
      Math.min(LLM_MAPPING_MAX_CALLS, 24)
    ),
    LLM_MAPPING_MAX_CALLS
  )
);
const LLM_LINE_ITEM_CLASSIFICATION_TIMEOUT_MS = Math.min(
  Number(process.env.LLM_LINE_ITEM_CLASSIFICATION_TIMEOUT_MS || 30_000),
  30_000
);
const LLM_LINE_ITEM_CLASSIFICATION_GROUP_TIMEOUT_MS = Number(
  Math.min(Number(process.env.LLM_LINE_ITEM_CLASSIFICATION_GROUP_TIMEOUT_MS || 45_000), 45_000)
);
const LLM_LINE_ITEM_CLASSIFICATION_MAX_ATTEMPTS_PER_BATCH = boundedPositiveNumber(
  process.env.LLM_LINE_ITEM_CLASSIFICATION_MAX_ATTEMPTS_PER_BATCH,
  2,
  2
);
const LLM_STATEMENT_CLASSIFICATION_CHUNK_SIZE = boundedPositiveNumber(
  process.env.LLM_STATEMENT_CLASSIFICATION_CHUNK_SIZE,
  8,
  12
);
const LLM_PREFILL_ANALYST_MATERIALITY_USD = Number(process.env.LLM_PREFILL_ANALYST_MATERIALITY_USD || 500_000);
const LLM_FULL_STATEMENT_COVERAGE =
  booleanEnv(process.env.ALLOW_LEGACY_LLM_FULL_STATEMENT_COVERAGE, false) &&
  booleanEnv(process.env.LLM_FULL_STATEMENT_COVERAGE, false);
const LLM_REQUIRE_FULL_STATEMENT_COVERAGE =
  LLM_FULL_STATEMENT_COVERAGE && booleanEnv(process.env.LLM_REQUIRE_FULL_STATEMENT_COVERAGE, false);

function positiveNumber(value: string | number | undefined, fallback: number) {
  const parsed = Number(value ?? fallback);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function boundedPositiveNumber(value: string | number | undefined, fallback: number, max: number) {
  return Math.min(positiveNumber(value, fallback), positiveNumber(max, fallback));
}

function nonNegativeNumber(value: string | number | undefined, fallback: number) {
  const parsed = Number(value ?? fallback);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

function booleanEnv(value: string | undefined, fallback: boolean) {
  if (value === undefined || value.trim() === "") return fallback;
  return /^(true|1|yes)$/i.test(value);
}

function normalizeConfiguredLlmModel(model: string, fallback: string) {
  const trimmed = model.trim();
  if (!trimmed) return fallback;
  const normalized = trimmed.toLowerCase();
  if (/^openrouter\/(?:owl-alpha|horizon-alpha|horizon-beta)$/.test(normalized)) return DEFAULT_LLM_MAPPING_FAST_MODEL;
  return trimmed;
}

function llmFallbackModels(raw: string | undefined, defaults: string[], primary: string) {
  const configured = raw
    ? raw
        .split(",")
        .map((item) => normalizeConfiguredLlmModel(item, ""))
        .filter(Boolean)
    : defaults;
  const primaryKey = primary.toLowerCase();
  const seen = new Set<string>([primaryKey]);
  return configured
    .map((item) => normalizeConfiguredLlmModel(item, ""))
    .filter(Boolean)
    .filter((item) => {
      const key = item.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

